// src/jsx/Register.jsx
import React, { useState } from "react";
import { createUserWithEmailAndPassword } from "firebase/auth";
import { auth, db, storage } from "../js/firebaseConfig";
import { doc, setDoc, serverTimestamp } from "firebase/firestore";
import { ref, uploadBytes, getDownloadURL } from "firebase/storage";

export default function Register({ setScreen }) {
    const [nome, setNome] = useState("");
    const [email, setEmail] = useState("");
    const [senha, setSenha] = useState("");
    const [senha2, setSenha2] = useState("");
    const [avatarFile, setAvatarFile] = useState(null);
    const [loading, setLoading] = useState(false);

    const cadastrar = async () => {
        if (!nome.trim()) return alert("Informe seu nome.");
        if (!email.trim()) return alert("Informe seu email.");
        if (senha.length < 6) return alert("Senha deve ter ao menos 6 caracteres.");
        if (senha !== senha2) return alert("Senhas não conferem.");

        setLoading(true);
        try {
            const userCred = await createUserWithEmailAndPassword(auth, email, senha);
            const uid = userCred.user.uid;

            let avatarUrl = "";
            if (avatarFile) {
                const avatarRef = ref(storage, `avatars/${uid}/${avatarFile.name}`);
                await uploadBytes(avatarRef, avatarFile);
                avatarUrl = await getDownloadURL(avatarRef);
            }

            await setDoc(doc(db, "users", uid), {
                nome,
                email,
                avatarUrl,
                createdAt: serverTimestamp()
            });

            alert("Conta criada com sucesso! Faça login.");
            setScreen("login");
        } catch (err) {
            console.error(err);
            alert("Erro ao criar conta: " + (err.message || err));
        } finally {
            setLoading(false);
        }
    };

    return (
        <div className="login-container">
            <h2>Criar Conta</h2>

            <input placeholder="Nome" value={nome} onChange={e => setNome(e.target.value)} />
            <input placeholder="Email" value={email} onChange={e => setEmail(e.target.value)} />
            <input placeholder="Senha" type="password" value={senha} onChange={e => setSenha(e.target.value)} />
            <input placeholder="Confirmar senha" type="password" value={senha2} onChange={e => setSenha2(e.target.value)} />

            <div style={{ marginTop: 8, marginBottom: 8 }}>
                <label style={{ display: "block", marginBottom: 6 }}>Avatar (opcional)</label>
                <input type="file" accept="image/*" onChange={(e) => setAvatarFile(e.target.files[0] || null)} />
            </div>

            <button onClick={cadastrar} disabled={loading}>{loading ? "Criando..." : "Cadastrar"}</button>

            <p style={{ marginTop: "20px", cursor: "pointer" }} onClick={() => setScreen("login")}>Voltar ao Login</p>
        </div>
    );
}
